import{_ as t}from"./chunks/analytics_hopr.CdeS75_P.js";import{_ as s,H as n,c as r,b as d,a2 as a,K as i}from"./chunks/framework.BEqfOpL-.js";const l="/images/analytics_hopr_episodes.webp",p="/images/analytics_hopr_audience.webp",_=JSON.parse(`{"title":"hopr.fm download analytics","description":"hopr.fm measures requests that pass through your show's download prefix and separates counted downloads from requests excluded by its rules. Use the report to understand download trends, episode launches and unusual traffic. A counted download does not verify a human listener or a completed listen.","frontmatter":{},"headers":[],"relativePath":"features/hopr-fm-analytics.md","filePath":"features/hopr-fm-analytics.md"}`),h={name:"features/hopr-fm-analytics.md"};function u(c,e,g,f,m,w){const o=n("HelpWalkthrough");return d(),r("div",null,[e[0]||(e[0]=a('<h1 id="hopr-fm-download-analytics" tabindex="-1">hopr.fm download analytics <a class="header-anchor" href="#hopr-fm-download-analytics" aria-label="Permalink to &quot;hopr.fm download analytics&quot;">​</a></h1><p>hopr.fm measures requests that pass through your show&#39;s download prefix and separates counted downloads from requests excluded by its rules. Use the report to understand download trends, episode launches and unusual traffic. A counted download does not verify a human listener or a completed listen.</p><p><strong>To access:</strong> choose your podcast → <strong>Analytics → hopr.fm</strong>. Reports are private to your account. If you see setup instructions, follow <a href="/features/analytics-connections.html#hopr-fm-podseo-s-download-prefix">Set up the hopr.fm prefix</a>. The prefix needs to be supported and published by your hosting platform.</p><p><a href="/images/analytics_hopr.webp" title="Open screenshot at full size"><img src="'+t+'" alt="hopr.fm request totals with counted and excluded shares"></a></p><h2 id="read-counted-downloads-and-requests" tabindex="-1">Read counted downloads and requests <a class="header-anchor" href="#read-counted-downloads-and-requests" aria-label="Permalink to &quot;Read counted downloads and requests&quot;">​</a></h2><p>In <strong>Overview</strong>, choose <strong>30</strong>, <strong>90</strong> or <strong>365 days</strong>. The request summary separates <strong>Counted downloads</strong> and <strong>Not counted</strong> as shares of requests analysed. <strong>Daily counted downloads</strong> shows the counted trend. Days use <strong>UTC</strong>, and today&#39;s data is partial.</p><p>hopr.fm counts at most one download for the same listener, episode and UTC day. A spike can include bulk downloads or other automated behaviour, so look at the breakdown before interpreting it as audience growth.</p><h2 id="investigate-a-day-and-an-exclusion-reason" tabindex="-1">Investigate a day and an exclusion reason <a class="header-anchor" href="#investigate-a-day-and-an-exclusion-reason" aria-label="Permalink to &quot;Investigate a day and an exclusion reason&quot;">​</a></h2><ol><li>Select a day on <strong>Daily counted downloads</strong>, or choose it in <strong>Request breakdown</strong>.</li><li>Read the updated request summary and <strong>What was left out</strong> for that day.</li><li>Select a reason, such as bots or bulk catalog downloads, to highlight when it occurred in <strong>Daily requests · counted and excluded</strong>. Other requests fade while the scale stays the same.</li><li>Use <strong>Show all reasons</strong> to clear that focus, then choose <strong>Whole period</strong> to return to the full range.</li></ol>',9)),i(o,{src:"/walkthroughs/hopr-breakdown.webp",poster:"/images/analytics_hopr_breakdown.webp",alt:"Select a day in hopr.fm, inspect excluded requests and highlight a reason in the timeline",duration:21050}),e[1]||(e[1]=a('<p>The bars in <strong>What was left out</strong> show each reason&#39;s share of excluded requests, not of all requests. Expand <strong>Apps &amp; tools observed</strong> for available examples. <strong>Inside the … counted downloads</strong> explains the standard and unusual patterns that remain counted.</p><p><strong>Show not counted</strong> changes the timeline display. It does not change your counting policy. The separate <strong>Count them / Stop counting them</strong> actions for podcast apps on cloud networks and <strong>Don&#39;t count / Count</strong> actions for unusual patterns do change which downloads are included. Read the notice before changing them; an unusual pattern alone is not proof of a bot. <strong>What we saw</strong> provides the available observations.</p><h2 id="compare-episode-launches" tabindex="-1">Compare episode launches <a class="header-anchor" href="#compare-episode-launches" aria-label="Permalink to &quot;Compare episode launches&quot;">​</a></h2><p>Open <strong>Episodes</strong>. <strong>Episode launches</strong> compares accumulated downloads over each episode&#39;s first 30 days. The newest episode is orange, and the dashed line is the typical episode. Compare the same age after publication; a three-day-old episode is not a complete month.</p><p><a href="/images/analytics_hopr_episodes.webp" title="Open screenshot at full size"><img src="'+l+'" alt="hopr.fm launch curves and episode download list"></a></p><p>The list underneath shows downloads in the selected report period, which differs from a first-30-days launch curve. Older episodes without complete measurement from release cannot provide a complete launch comparison.</p><h2 id="explore-audience" tabindex="-1">Explore Audience <a class="header-anchor" href="#explore-audience" aria-label="Permalink to &quot;Explore Audience&quot;">​</a></h2><p><strong>Audience</strong> contains <strong>When your audience downloads</strong>, app shares over time, downloads by app and a country map.</p><p><a href="/images/analytics_hopr_audience.webp" title="Open screenshot at full size"><img src="'+p+'" alt="hopr.fm audience download timing, app shares and geography"></a></p><p>The day/hour view uses the listener&#39;s local time, unlike the UTC daily request view. Automatic podcast downloads often happen when you publish, so a busy release hour is not necessarily the hour people listen. The app and country reports describe counted downloads, not unique listeners. Where a country map is available, expand <strong>All reported countries</strong> and select a country to highlight it and read its reported share.</p><h2 id="setup-warnings-and-unexplained-spikes" tabindex="-1">Setup warnings and unexplained spikes <a class="header-anchor" href="#setup-warnings-and-unexplained-spikes" aria-label="Permalink to &quot;Setup warnings and unexplained spikes&quot;">​</a></h2><p>If PodSEO cannot find your prefix, check that the host saved it into the actual episode links. Some hosts apply a new prefix only to future episodes. A warning about another key means the feed uses a different account&#39;s prefix. Use your own prefix and the on-page check instructions.</p><p>Changing a prefix can cause apps to fetch the back catalog again. Review <strong>What was left out</strong> and the daily timeline before attributing the initial spike to new fans. To stop measuring new traffic, remove the prefix in your host; the separate <a href="/features/connections.html">Connections</a> screen is not a host-side feed editor.</p><p>Use <a href="/features/hosting-analytics.html">Hosting analytics</a> and other connected reports for context. Do not add prefix and host counts together: they can measure the same downloads with different rules.</p>',14))])}const x=s(h,[["render",u]]);export{_ as __pageData,x as default};
